fix:
Rewrite the formula so that each variable occurs exactly once.
```rust
fn parallel_resistors_correct(r1: Interval, r2: Interval) -> Interval {
    // Formula: 1 / (1/R1 + 1/R2) - R1 and R2 each occur exactly once
    let inv_r1 = Interval::one().div(r1);
    let inv_r2 = Interval::one().div(r2);
    Interval::one().div(inv_r1.add(inv_r2))
}
